package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity@Table(name="spms_calibration_participant",uniqueConstraints=@UniqueConstraint(name="uk_spms_calibration_participant",columnNames={"agency_id","calibration_case_id","employee_no"}))public class PerformanceCalibrationParticipant extends RspAuditedEntity{@Column(name="calibration_case_id",nullable=false,length=36)private String calibrationCaseId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name",nullable=false,length=300)private String employeeName;@Column(name="member_role",nullable=false,length=30)private String memberRole;@Column(nullable=false)private boolean voting;@Column(name="decision_eligible",nullable=false)private boolean decisionEligible;@Column(name="conflict_reason",length=200)private String conflictReason;protected PerformanceCalibrationParticipant(){}public PerformanceCalibrationParticipant(String a,String c,PerformanceManagementTeamMember m,boolean eligible,String conflict){super(a);calibrationCaseId=requiredText(c,"calibrationCaseId");employeeNo=m.getEmployeeNo();employeeName=m.getEmployeeNameSnapshot();memberRole=m.getRole().name();voting=m.isVoting();decisionEligible=eligible;conflictReason=optionalText(conflict);}public String getEmployeeNo(){return employeeNo;}public String getEmployeeName(){return employeeName;}public String getMemberRole(){return memberRole;}public boolean isVoting(){return voting;}public boolean isDecisionEligible(){return decisionEligible;}public String getConflictReason(){return conflictReason;}}
